/* Script to create and insert truncated sample data. 
Run scripts in schema titled pokemon */

CREATE TABLE `pokemon_cards` (
  `id` varchar(8) NOT NULL,
  `card_set` varchar(4) NOT NULL,
  `series` varchar(4) NOT NULL,
  `publisher` varchar(4) NOT NULL,
  `generation` varchar(5) NOT NULL,
  `release_date` varchar(50) DEFAULT NULL,
  `artist` varchar(15) NOT NULL,
  `card_name` varchar(10) NOT NULL,
  `set_num` int NOT NULL,
  `card_types` varchar(13) NOT NULL,
  `supertype` varchar(7) NOT NULL,
  `subtypes` varchar(11) NOT NULL,
  `card_level` int NOT NULL,
  `hp` int NOT NULL,
  `evolvesFrom` varchar(10) DEFAULT NULL,
  `evolvesTo` varchar(25) DEFAULT NULL,
  `abilities` varchar(378) DEFAULT NULL,
  `attacks` varchar(550) NOT NULL,
  `weaknesses` varchar(38) DEFAULT NULL,
  `retreatCost` varchar(39) DEFAULT NULL,
  `convertedRetreatCost` int DEFAULT NULL,
  `rarity` varchar(9) NOT NULL,
  `flavorText` varchar(103) NOT NULL,
  `nationalPokedexNumbers` varchar(5) NOT NULL,
  `legalities` varchar(22) NOT NULL,
  `resistances` varchar(39) DEFAULT NULL,
  `rules` varchar(30) DEFAULT NULL,
  `regulationMark` varchar(30) DEFAULT NULL,
  `ancientTrait` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


